		tcp dport { 22, 53, 111, 2379-2381, 6080, 6180, 6183, 6385, 6443, 9001, 9099-9100, 9103-9105, 9107-9108, 9258, 9443-9445, 9454, 9637, 9978-9980, 10250, 10256-10257, 10259, 17697, 18080, 22623-22624, 30000-32767 } accept
		udp dport { 53, 68, 111, 6081, 30000-32767 } accept
		ip daddr 255.255.255.255 jump {
			limit rate 1/minute burst 5 packets log prefix "firewall "
